#!/usr/bin/env python3
"""Full verification pass: adjacencies, routing, ping tests."""

import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def connect(host, device_type, username, password):
    return ConnectHandler(
        host=host, device_type=device_type,
        username=username, password=password,
        read_timeout_override=30
    )

NON_GUEST_HOSTS = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}

GUEST_HOSTS = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

ALL_HOSTS = {**NON_GUEST_HOSTS, **GUEST_HOSTS}

def ping_from_host(mgmt_ip, src_name, targets):
    """Ping multiple targets from a host. Returns list of (src, dst_name, dst_ip, success)."""
    results = []
    try:
        conn = connect(mgmt_ip, "linux", "root", "alpine")
        for dst_name, dst_ip in targets:
            out = conn.send_command(f"ping -c 2 -W 3 {dst_ip}", read_timeout=15)
            success = "bytes from" in out or "0% packet loss" in out
            results.append((src_name, dst_name, dst_ip, success))
        conn.disconnect()
    except Exception as e:
        for dst_name, dst_ip in targets:
            results.append((src_name, dst_name, dst_ip, False))
    return results

def main():
    print("=" * 60)
    print("VERIFICATION PASS")
    print("=" * 60)

    # 1. Non-guest to non-guest pings (should all pass)
    print("\n--- Non-guest to non-guest pings ---")
    all_results = []
    futures = []
    with ThreadPoolExecutor(max_workers=10) as pool:
        for src_name, (mgmt_ip, src_lab_ip) in NON_GUEST_HOSTS.items():
            targets = []
            for dst_name, (_, dst_lab_ip) in NON_GUEST_HOSTS.items():
                if src_name != dst_name:
                    targets.append((dst_name, dst_lab_ip))
            # Also add internet targets
            targets.append(("8.8.8.8", "8.8.8.8"))
            targets.append(("1.1.1.1", "1.1.1.1"))
            futures.append(pool.submit(ping_from_host, mgmt_ip, src_name, targets))

        for f in as_completed(futures):
            all_results.extend(f.result())

    # Separate internal and internet results
    ng_pass = 0
    ng_fail = 0
    ng_failures = []
    inet_pass = 0
    inet_fail = 0
    inet_failures = []

    for src, dst, ip, ok in all_results:
        if ip in ("8.8.8.8", "1.1.1.1"):
            if ok:
                inet_pass += 1
            else:
                inet_fail += 1
                inet_failures.append(f"  {src} -> {dst}")
        else:
            if ok:
                ng_pass += 1
            else:
                ng_fail += 1
                ng_failures.append(f"  {src} -> {dst} ({ip})")

    print(f"Non-guest to non-guest: {ng_pass} pass, {ng_fail} fail")
    for f in ng_failures:
        print(f)
    print(f"Non-guest to internet: {inet_pass} pass, {inet_fail} fail")
    for f in inet_failures:
        print(f)

    # 2. Guest to guest (should pass)
    print("\n--- Guest to guest pings ---")
    guest_results = []
    futures = []
    with ThreadPoolExecutor(max_workers=2) as pool:
        for src_name, (mgmt_ip, src_lab_ip) in GUEST_HOSTS.items():
            targets = []
            for dst_name, (_, dst_lab_ip) in GUEST_HOSTS.items():
                if src_name != dst_name:
                    targets.append((dst_name, dst_lab_ip))
            targets.append(("8.8.8.8", "8.8.8.8"))
            targets.append(("1.1.1.1", "1.1.1.1"))
            futures.append(pool.submit(ping_from_host, mgmt_ip, src_name, targets))

        for f in as_completed(futures):
            guest_results.extend(f.result())

    g_pass = 0
    g_fail = 0
    g_failures = []
    gi_pass = 0
    gi_fail = 0
    gi_failures = []

    for src, dst, ip, ok in guest_results:
        if ip in ("8.8.8.8", "1.1.1.1"):
            if ok:
                gi_pass += 1
            else:
                gi_fail += 1
                gi_failures.append(f"  {src} -> {dst}")
        else:
            if ok:
                g_pass += 1
            else:
                g_fail += 1
                g_failures.append(f"  {src} -> {dst} ({ip})")

    print(f"Guest to guest: {g_pass} pass, {g_fail} fail")
    for f in g_failures:
        print(f)
    print(f"Guest to internet: {gi_pass} pass, {gi_fail} fail")
    for f in gi_failures:
